# Recursively solve the delta spectrum: look for structural patterns such as mirrored regions,
# periodic wave-like sequences, and inflection (torsion inversion) points.

# First, we reload the data from before
hash_hex = "a18a44d025a2a2fb944da114af7e0e9109ebf92324a8411004b640fa204cb21a"
nibbles = [int(c, 16) for c in hash_hex]
mid = len(nibbles) // 2
stack_A = nibbles[:mid]
stack_B = list(reversed(nibbles[mid:]))
delta_spectrum = [a - b for a, b in zip(stack_A, stack_B)]

import numpy as np

# Recursive pattern analysis functions
def find_mirror_regions(seq):
    length = len(seq)
    mirrors = []
    for size in range(2, length // 2 + 1):
        for i in range(length - size + 1):
            left = seq[i:i+size]
            right = seq[i+size:i+2*size]
            if right == left[::-1]:
                mirrors.append((i, size))
    return mirrors

def find_periodicity(seq):
    period_scores = {}
    for p in range(2, len(seq)//2):
        slices = [seq[i::p] for i in range(p)]
        mean_var = np.mean([np.var(s) for s in slices])
        period_scores[p] = mean_var
    return sorted(period_scores.items(), key=lambda x: x[1])

def detect_zero_crossings(seq):
    crossings = []
    for i in range(1, len(seq)):
        if seq[i-1] * seq[i] < 0:
            crossings.append(i)
    return crossings

# Run recursive structure detection
mirror_regions = find_mirror_regions(delta_spectrum)
periodic_patterns = find_periodicity(delta_spectrum)
zero_crossings = detect_zero_crossings(delta_spectrum)

import pandas as pd
results_df = pd.DataFrame({
    "Index": list(range(len(delta_spectrum))),
    "Δ": delta_spectrum
})

import ace_tools as tools; tools.display_dataframe_to_user(name="Recursive SHA Delta Analysis", dataframe=results_df)

# Return recursive features for assistant context
{
    "mirror_regions": mirror_regions,
    "periodic_patterns_top": periodic_patterns[:5],
    "zero_crossings": zero_crossings
}

